KG42.register("nodes-664b13449b6052e8ad75572e",{"id":"COMP-221ff4096aa50456","code":"BID015","label":"Consumption-demand quantity submission before deducting generation","definition":"Participants or their aggregation agents report to the organizer the quantity of consumption demand formed by autonomous choice or local dispatch; separate declaration, aggregation mapping, and provisional updates are retained according to source.","layer":"L3","template_code":"PGR","concept_id":"bidding.demand","concept_ids":["bidding.demand"],"identity_dimensions":{"identity_fields":["Submitter: the decision-maker for consumption arrangements or its aggregation agent.","Object: the quantity of consumption demand not offset by generation.","Function: disclose the consumption-side quantity decision to the organizer."]},"exclusions":[["e_{dem,t}^bid=Σ_{δ∈A_f}x_{δ,t}*+x_t^{ch*}/η^{ch}+P_t^{must-run}, submitted period by period over the dispatch horizon T.","Demand includes the optimal power of flexible appliances, efficiency-adjusted EV charging power, and must-run load; it must be listed separately from generation, and the total net demand alone must not be reported.","This demand declaration serves as an exogenous input to regional aggregate pricing."],["After receiving the internal price for the next time slot, the PV prosumer selects x_n^o and submits it to the MGO.","Hourly advance scheduling is adopted, and submission occurs after price broadcasting and flexible-load evaluation; the underlying strategy satisfies x_n^min≤x_n≤x_n^max."],["Submit to the DSO p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}), ∀t∈N_t; p is EV charging power, \\hat p is HP power, and E_i maps customers to load buses.","Given the current-round DPT, the local plan minimizes the sum of electricity cost and network charges, subject to EV operation, household thermal conditions, and HP input power limits.","The submitted quantity is provisional demand, updated in DPT iterations and used for subsequent congestion identification; it is not equivalent to the allocated electricity quantity."]],"members":[{"id":"11-p2p_mechanisms_evaluation::v141-c-R011::V::bidding.demand","rule_id":"v141-c-R011","market_meaning":"Each energy bid must report demand separately from generation at every time step, rather than reporting only overall net demand. Scope: Demand information in each participant's MMR energy bid.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Demand information in each participant's MMR energy bid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-ev-06"]},"constraint_refs":["11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C001","11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C002"],"decision_anchor":"bidding.demand","source_rule_sha256":"f2f5ee8b3a4400520c812e369521b99a6c756ae509e728e1811dfd4a5dd2ae07","paper":"11-p2p_mechanisms_evaluation","rule_ref":"11-p2p_mechanisms_evaluation::v141-c-R011","node_id":"bidding.demand","function":"bidding.demand","unit_id":"11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","mechanism_id":"v141-a-M02","anchor":true},{"id":"11-p2p_mechanisms_evaluation::v141-c-R014::V::bidding.demand","rule_id":"v141-c-R014","market_meaning":"Submitted generation quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. Submitted demand quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. The coordinator calculates internal prices using the MMR pricing model. Scope: MMR pricing within one energy sharing region. The internal buying and selling prices are equal to the arithmetic mean of the retailer's export and retail prices. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation equals total demand. The internal selling price remains the arithmetic mean of export and retail prices; the internal buying price is adjusted to cover the regional deficit imported at the retailer's retail price. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation is less than total demand. The internal buying price remains the arithmetic mean of export and retail prices; the internal selling price is adjusted to incorporate surplus-export income for distribution among participants providing electricity through generation or EV discharging. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation exceeds total demand.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"MMR internal prices at a given time step within one energy sharing region. | MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. | MMR pricing within one energy sharing region.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},"constraint_refs":["11-p2p_mechanisms_evaluation::v141-c-R014::v141-c-R014-C002"],"decision_anchor":"pricing.local","source_rule_sha256":"a224bf63fdbdff5bed026ae7e29a057b5ec0c0bbb01e1bf9b93de0d872bafc47","paper":"11-p2p_mechanisms_evaluation","rule_ref":"11-p2p_mechanisms_evaluation::v141-c-R014","node_id":"bidding.demand","function":"bidding.demand","unit_id":"11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","mechanism_id":"v141-a-M02","anchor":false},{"id":"14-stackelberg_pv_sharing::v141-c-R001::V::bidding.demand","rule_id":"v141-c-R001","market_meaning":"Broadcasting the next-slot internal prices precedes submission of the prosumers' chosen next-slot consumption quantities to MGO. Scope: The numbered next-slot ESM scheduling procedure within the microgrid, including every participating prosumer's submission of optimal consumption.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"The numbered next-slot ESM scheduling procedure within the microgrid, including every participating prosumer's submission of optimal consumption.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E04"]},"constraint_refs":["14-stackelberg_pv_sharing::v141-c-R001::v141-c-R001-C001"],"decision_anchor":"bidding.demand","source_rule_sha256":"78439c26a391aea634b0125d8afaefe59b64ce9bb17a0ea1f43443bf48d0e0d2","paper":"14-stackelberg_pv_sharing","rule_ref":"14-stackelberg_pv_sharing::v141-c-R001","node_id":"bidding.demand","function":"bidding.demand","unit_id":"14-stackelberg_pv_sharing::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":true},{"id":"14-stackelberg_pv_sharing::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"Each prosumer submits its chosen next-slot energy-consumption quantity x_n^o to the MGO. Scope: Hour-ahead ESM within the microgrid; submission of each prosumer's chosen total consumption for the next time slot. The MGO is obligated to pursue maximization of its own profit when coordinating PV energy sharing. Scope: The MGO's objective in the Stackelberg energy-sharing arrangement. The MGO is required to trade with the utility grid to balance supplies and demands. Scope: The microgrid operator's external balancing duty under ESM. Condition: An internal mismatch occurs between PV power generation and load power demand. A server should be deployed in the MGO. Scope: Infrastructure at the MGO for implementing ESM. Condition: Implementation of the ESM.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Hour-ahead ESM within the microgrid; submission of each prosumer's chosen total consumption for the next time slot. | Infrastructure at the MGO for implementing ESM. | The MGO's objective in the Stackelberg energy-sharing arrangement. | The microgrid operator's external balancing duty under ESM.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e001","v141-b-g01-e005","v141-b-g01-e020","v141-b-g01-e021"]},"constraint_refs":["14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C001","14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C005"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"0d8e892f31e0d5302dacb59afdc173bdc4228ba3a65407577a9a7b02d7bb6d8a","paper":"14-stackelberg_pv_sharing","rule_ref":"14-stackelberg_pv_sharing::v141-c-R003","node_id":"bidding.demand","function":"bidding.demand","unit_id":"14-stackelberg_pv_sharing::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":false},{"id":"39-dynamic_congestion_tariff::v141-c-R001::V::bidding.demand","rule_id":"v141-c-R001","market_meaning":"DPT price signals guide aggregators' updates of the demand quantities represented by their tentative purchasing plans, whose results are returned to the DSO as demand responses. Scope: Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. Condition: Within the iterative process, using the DPT signals received for the current planning update. Each aggregator's tentative purchasing quantities are planned to minimize energy cost plus network tariff cost, subject to EV operating limits, household thermal limits and HP input-power limits. Scope: Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands. Condition: During the DPT iterative planning process.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. | Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e004","v141-b-g02-e015","v141-b-g13-E13","v141-b-g19-E19"]},"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C001","39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C002","39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C003"],"decision_anchor":"bidding.demand","source_rule_sha256":"9b8e778b4854afd0b41ecd058db42873ffec108c38fd9de44e37a205a86ffd4a","paper":"39-dynamic_congestion_tariff","rule_ref":"39-dynamic_congestion_tariff::v141-c-R001","node_id":"bidding.demand","function":"bidding.demand","unit_id":"39-dynamic_congestion_tariff::v141-a-M02::bidding.demand","mechanism_id":"v141-a-M02","anchor":true},{"id":"39-dynamic_congestion_tariff::v141-c-R002::V::bidding.demand","rule_id":"v141-c-R002","market_meaning":"Aggregators submit their tentative demand plans to the DSO. Scope: DPT distributed congestion-management iterations between aggregators and the DSO. The DSO-side formulation checks network limits without a DSO-side optimization model. Scope: DSO-side formulation of DPT congestion management. The DSO needs to forecast conventional active and reactive power consumption at each load point; it need not forecast price sensitivities or flexible demands for the DPT method. Scope: DSO forecasting responsibilities under the DPT method.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"DPT distributed congestion-management iterations between aggregators and the DSO. | DSO forecasting responsibilities under the DPT method. | DSO-side formulation of DPT congestion management.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e025","v141-b-g13-E13","v141-b-g21-E21"]},"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R002::v141-c-R002-C001"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"3abc1bfafb81e0f5da3f20b028060962f71b9a9fd8ae8b1909761c869abdca1d","paper":"39-dynamic_congestion_tariff","rule_ref":"39-dynamic_congestion_tariff::v141-c-R002","node_id":"bidding.demand","function":"bidding.demand","unit_id":"39-dynamic_congestion_tariff::v141-a-M02::bidding.demand","mechanism_id":"v141-a-M02","anchor":false},{"id":"39-dynamic_congestion_tariff::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"Tentative demand-response submissions provide the information used to identify congestion and modify DPT coordination signals accordingly. Scope: Iterative DPT congestion-management planning between aggregators and the DSO. DPT coordination determines a rate for each load bus and time period according to network conditions and forecast nonflexible load, with the objective that aggregator energy schedules respect network limits. Scope: DPT rate determination for distribution-network congestion-management planning. The tentative DPT signals are initialized to zero. Scope: Initialization of the iterative DPT coordination procedure. Condition: At initiation of the iterative process. The DPT coordination process continues iterating until network constraints are satisfied and final DPT rates are determined. Scope: Continuation and termination of iterative DPT coordination. The line-flow and voltage marginal-price signals are constrained to be nonnegative before transformation into DPTs. Scope: Internal signal restrictions in iterative DPT calculation. The final DPT rates equal the last iteration DPT rates. Scope: Finalization of iterative DPT signals. Condition: When the DPT iteration converges.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Continuation and termination of iterative DPT coordination. | DPT rate determination for distribution-network congestion-management planning. | Finalization of iterative DPT signals. | Initialization of the iterative DPT coordination procedure. | Internal signal restrictions in iterative DPT calculation. | Iterative DPT congestion-management planning between aggregators and the DSO.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e013","v141-b-g02-e016","v141-b-g12-E12","v141-b-g13-E13"]},"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C001","39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C007"],"decision_anchor":"coordination.price_signal","source_rule_sha256":"6a53d1884a87227f2824a56d42c5278649a7c6a0e0e98b1d2694e6249181d473","paper":"39-dynamic_congestion_tariff","rule_ref":"39-dynamic_congestion_tariff::v141-c-R003","node_id":"bidding.demand","function":"bidding.demand","unit_id":"39-dynamic_congestion_tariff::v141-a-M02::bidding.demand","mechanism_id":"v141-a-M02","anchor":false}],"paper_ids":["11-p2p_mechanisms_evaluation","14-stackelberg_pv_sharing","39-dynamic_congestion_tariff"],"evidence":[{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)","paper":"11-p2p_mechanisms_evaluation","rule_id":"v141-c-R011","quote":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"},{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)","paper":"11-p2p_mechanisms_evaluation","rule_id":"v141-c-R014","quote":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"},{"evidence_id":"v141-b-g07-ev-07","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-pricing","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A25-A27","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region. If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:\n\np_t^{buy} = p_t^{sell} = r_t^{average} = \\frac{(r_t^{export} + r_t^{retail})}{2}, \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| = \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A25)\n\nIf the generation is less than demand, the deficit generation has to be supplied by the power imported from the retailer at the retail price, and the cost of this import should be covered. Therefore, in this situation, the internal selling price keeps the same as that in Formula (A25), but the buying price is modified:\n\n\\begin{cases} p_t^{buy} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\right) \\cdot r_t^{retail}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}} \\\\ p_t^{sell} = r_t^{average} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \u003c \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A26)\n\nSimilarly, if the generation is higher than demand, the surplus generation needs to be sold to the retailer at the export price, and this part of income needs to be distributed among all the prosumers who provide electricity by generation or EV discharging. The internal price is calculated as follows:\n\n\\begin{cases} p_t^{buy} = r_t^{average} \\\\ p_t^{sell} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\right) \\cdot r_t^{export}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}|} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| > \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A27)\n\nFormulas (A25)-(A27) compose the pricing model in the coordinator agent under mid-market rate mechanism.","paper":"11-p2p_mechanisms_evaluation","rule_id":"v141-c-R014","quote":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region. If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:\n\np_t^{buy} = p_t^{sell} = r_t^{average} = \\frac{(r_t^{export} + r_t^{retail})}{2}, \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| = \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A25)\n\nIf the generation is less than demand, the deficit generation has to be supplied by the power imported from the retailer at the retail price, and the cost of this import should be covered. Therefore, in this situation, the internal selling price keeps the same as that in Formula (A25), but the buying price is modified:\n\n\\begin{cases} p_t^{buy} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\right) \\cdot r_t^{retail}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}} \\\\ p_t^{sell} = r_t^{average} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \u003c \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A26)\n\nSimilarly, if the generation is higher than demand, the surplus generation needs to be sold to the retailer at the export price, and this part of income needs to be distributed among all the prosumers who provide electricity by generation or EV discharging. The internal price is calculated as follows:\n\n\\begin{cases} p_t^{buy} = r_t^{average} \\\\ p_t^{sell} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\right) \\cdot r_t^{export}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}|} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| > \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A27)\n\nFormulas (A25)-(A27) compose the pricing model in the coordinator agent under mid-market rate mechanism."},{"evidence_id":"v141-b-g02-E04","location":{"location_id":"src-ed046424ff-p04-c2r2__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.C Implementation Process","anchor_text":"n- set as λs and λb, respectively. 2) Every prosumer submits ˆEgn, kn, and the role of buyer or re s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"3) Considering (26) and (27) belong to nonlinear programming problem, the MGO can solve (30) and obtain the internal prices p_{s} and p_{b} for the next time slot by using interior point method. 4) The MGO broadcasts the internal prices of next time slot to all the prosumers; 5) Each prosumer evaluates the flexible load of the next time slot, and decides the optimal energy consumption x_{o}^{n}. 6) Every prosumer sends x_{o}^{n} to the MGO, the energy sharing of the next time slot is decided.","paper":"14-stackelberg_pv_sharing","rule_id":"v141-c-R001","quote":"3) Considering (26) and (27) belong to nonlinear programming problem, the MGO can solve (30) and obtain the internal prices p_{s} and p_{b} for the next time slot by using interior point method. 4) The MGO broadcasts the internal prices of next time slot to all the prosumers; 5) Each prosumer evaluates the flexible load of the next time slot, and decides the optimal energy consumption x_{o}^{n}. 6) Every prosumer sends x_{o}^{n} to the MGO, the energy sharing of the next time slot is decided."},{"evidence_id":"v141-b-g01-e020","location":{"location_id":"src-ed046424ff-p04-c2r2__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.C Implementation Process","anchor_text":"n- set as λs and λb, respectively. 2) Every prosumer submits ˆEgn, kn, and the role of buyer or re s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Each prosumer evaluates the flexible load of the next time slot, and decides the optimal energy consumption x_n^o. Every prosumer sends x_n^o to the MGO, the energy sharing of the next time slot is decided.","paper":"14-stackelberg_pv_sharing","rule_id":"v141-c-R003","quote":"Each prosumer evaluates the flexible load of the next time slot, and decides the optimal energy consumption x_n^o. Every prosumer sends x_n^o to the MGO, the energy sharing of the next time slot is decided."},{"evidence_id":"v141-b-g01-e015","location":{"location_id":"src-ed046424ff-p04-c1r1__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.A Formulation of Stackelberg Game","anchor_text":"LIU et al.: ENERGY SHARING MANAGEMENT FOR MICROGRIDS WITH PV PROSUM by changing their energy consump","equation_id":"(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The game is formally defined by its strategic form as L = {(G ∪ {MGO}), {X_n}_{n∈G}, {P_b}, {P_s}, {U_n}_{n∈G}, R} (6) which consists of the following components: 1) The prosumers in set G act as followers and choose their optimal consumption in response to the internal prices set by the MGO, the leader of the game. 2) X_n is the set of strategies of prosumer n, which is constrained by x_n^min ≤ x_n ≤ x_n^max. 3) P_b and P_s are the sets of strategies set by MGO, which are the vectors of the internal prices p_b and p_s, respectively. It should be ensured that the internal prices are constrained by λ^s ≤ p_s \u003c p_b ≤ λ^b_n. 4) U_n is the utility function of prosumer n, as shown in (1) that captures the prosumer's benefit from consuming energy x_n and sharing energy E_n^g − x_n with other prosumers in the microgrid. 5) R is the profit function of MGO, as shown in (5) that captures the total profit incurred by the sharing energy inside the microgrid and trading with the utility grid.","paper":"14-stackelberg_pv_sharing","rule_id":"v141-c-R003","quote":"The game is formally defined by its strategic form as L = {(G ∪ {MGO}), {X_n}_{n∈G}, {P_b}, {P_s}, {U_n}_{n∈G}, R} (6) which consists of the following components: 1) The prosumers in set G act as followers and choose their optimal consumption in response to the internal prices set by the MGO, the leader of the game. 2) X_n is the set of strategies of prosumer n, which is constrained by x_n^min ≤ x_n ≤ x_n^max. 3) P_b and P_s are the sets of strategies set by MGO, which are the vectors of the internal prices p_b and p_s, respectively. It should be ensured that the internal prices are constrained by λ^s ≤ p_s \u003c p_b ≤ λ^b_n. 4) U_n is the utility function of prosumer n, as shown in (1) that captures the prosumer's benefit from consuming energy x_n and sharing energy E_n^g − x_n with other prosumers in the microgrid. 5) R is the profit function of MGO, as shown in (5) that captures the total profit incurred by the sharing energy inside the microgrid and trading with the utility grid."},{"evidence_id":"v141-b-g01-e006","location":{"location_id":"src-ed046424ff-p02-c1r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. INTRODUCTION","anchor_text":"g p p mentioned studies, two main differences have been made. The as ﬁrst is the role of participant","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"unknown"},"source_text":"In this paper, every prosumer has equal privilege which means prosumers are participated in the microgrid operation equipotently. Thus, we select MGO as the leader, which means that the MGO determines the buying and selling prices simultaneously. And the prosumers act as followers to adjust their energy consumption behaviors according to the time-varying prices.","paper":"14-stackelberg_pv_sharing","rule_id":"v141-c-R003","quote":"In this paper, every prosumer has equal privilege which means prosumers are participated in the microgrid operation equipotently. Thus, we select MGO as the leader, which means that the MGO determines the buying and selling prices simultaneously. And the prosumers act as followers to adjust their energy consumption behaviors according to the time-varying prices."},{"evidence_id":"v141-b-g02-e015","location":{"location_id":"src-c263a83472-p05-c1r4__v141-a-M02-coordination","page":5,"printed_page":null,"section":"III-B. Control Diagram of the Iteration Process","anchor_text":"g g p only be employed to calculate DT rates, but not the DPT rates. pa In Section III-B, the margin","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"From the DSO point of view, the price-based congestion management process is an indirect control process. The aggregators respond to the price signals from the DSO (e.g., DT or DPT), and the DSO can adjust the price signals such that the responses from the aggregators can respect the network limits. The control framework of the whole congestion management process is shown in Fig. 3. The target system comprises of the distribution network and two actors, i.e., the DSO and aggregators. The aggregators receive the DPTs and make their own optimal planning (DR). Then, the planning results are sent to the DSO.","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R001","quote":"From the DSO point of view, the price-based congestion management process is an indirect control process. The aggregators respond to the price signals from the DSO (e.g., DT or DPT), and the DSO can adjust the price signals such that the responses from the aggregators can respect the network limits. The control framework of the whole congestion management process is shown in Fig. 3. The target system comprises of the distribution network and two actors, i.e., the DSO and aggregators. The aggregators receive the DPTs and make their own optimal planning (DR). Then, the planning results are sent to the DSO."},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints.","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R001","quote":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."},{"evidence_id":"v141-b-g02-e004","location":{"location_id":"src-c263a83472-p04-c2r1__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"NETWORKS 2151 concept. The optimal planning problem for aggregator i is formulated as (1)-(5). min p","equation_id":"(1)-(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"An aggregator can use a quadratic function to represent the total cost including energy consumption and network tariff as shown in (1). The quadratic term in (1) is due to the DPT received from the DSO (R_t is the DPT; therefore, it is a fixed parameter for the optimizations at the aggregator side). The optimal planning problem for aggregator i is formulated as (1)-(5). \\min_{p_{i,t},\\hat p_{i,t}} \\sum_{t\\in N_T}(p_{i,t}+\\hat p_{i,t})^T E_i^T R_t E_i(p_{i,t}+\\hat p_{i,t}) + \\sum_{t\\in N_T}(c_t^1)^T(p_{i,t}+\\hat p_{i,t}) \\quad (1)","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R001","quote":"An aggregator can use a quadratic function to represent the total cost including energy consumption and network tariff as shown in (1). The quadratic term in (1) is due to the DPT received from the DSO (R_t is the DPT; therefore, it is a fixed parameter for the optimizations at the aggregator side). The optimal planning problem for aggregator i is formulated as (1)-(5). \\min_{p_{i,t},\\hat p_{i,t}} \\sum_{t\\in N_T}(p_{i,t}+\\hat p_{i,t})^T E_i^T R_t E_i(p_{i,t}+\\hat p_{i,t}) + \\sum_{t\\in N_T}(c_t^1)^T(p_{i,t}+\\hat p_{i,t}) \\quad (1)"},{"evidence_id":"v141-b-g19-E19","location":{"location_id":"src-c263a83472-p04-c2r2__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"t_≤t (2) pmini,t ≤pi,t ≤pmaxi,t ∀t ∈NT, (3) a- Ka,mini,t ≤ Ai,t,t_ˆpi,t_ + ui,t ≤Ka,maxi,t , ∀t ∈NT,","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Constraints (2) - (3) are from the limits of EVs. Constraint (4) represents the thermal limits of households and (5) gives the input power limits of HPs. Constraint (4) is derived from the thermal process analysis of the household and the HP as shown in [4].","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R001","quote":"Constraints (2) - (3) are from the limits of EVs. Constraint (4) represents the thermal limits of households and (5) gives the input power limits of HPs. Constraint (4) is derived from the thermal process analysis of the household and the HP as shown in [4]."},{"evidence_id":"v141-b-g02-e006","location":{"location_id":"src-c263a83472-p04-c2r2__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"t_≤t (2) pmini,t ≤pi,t ≤pmaxi,t ∀t ∈NT, (3) a- Ka,mini,t ≤ Ai,t,t_ˆpi,t_ + ui,t ≤Ka,maxi,t , ∀t ∈NT,","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After solving the optimal problem, the aggregator i will have a tentative optimal plan (p^*_{i,t}, \\hat p^*_{i,t}). Then (6) can be used to formulate the aggregated DR for aggregator i, which will be sent to the DSO.\np_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}), \\forall t\\in N_t \\quad (6)","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R001","quote":"After solving the optimal problem, the aggregator i will have a tentative optimal plan (p^*_{i,t}, \\hat p^*_{i,t}). Then (6) can be used to formulate the aggregated DR for aggregator i, which will be sent to the DSO.\np_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}), \\forall t\\in N_t \\quad (6)"},{"evidence_id":"v141-b-g20-E20","location":{"location_id":"src-c263a83472-p04-c2r3__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.2) Formulation at the DSO Side","anchor_text":"ent pai,t = Ei pi,t + ˆpi,t , ∀t ∈Nt (6) he 2) Formulation at the DSO Side: At the DSO side, there i","equation_id":"(6)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After solving the optimal problem, the aggregator \\(i\\) will have a tentative optimal plan \\((p_{i,t}^*,\\hat p_{i,t}^*)\\). Then (6) can be used to formulate the aggregated DR for aggregator \\(i\\), which will be sent to the DSO. \\[p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}),\\quad \\forall t\\in N_t \\tag{6}\\]","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R001","quote":"After solving the optimal problem, the aggregator \\(i\\) will have a tentative optimal plan \\((p_{i,t}^*,\\hat p_{i,t}^*)\\). Then (6) can be used to formulate the aggregated DR for aggregator \\(i\\), which will be sent to the DSO. \\[p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}),\\quad \\forall t\\in N_t \\tag{6}\\]"},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints.","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R002","quote":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints.","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R003","quote":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."},{"evidence_id":"v141-b-g02-e011","location":{"location_id":"src-c263a83472-p05-c1r2__v141-a-M02-pricing","page":5,"printed_page":null,"section":"III-A. Mathematical Formulation of DPT Method","anchor_text":"t ) t Then, λt, ωt and Rt can be updated by, λ(k+1)t = λ(k)t + α DRe s(k)t −Ft , ∀t ∈NT, (11) 1 V ω(","equation_id":"(11)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Then, \\lambda_t, \\omega_t and R_t can be updated by,\n\\lambda_t^{(k+1)}=\\lambda_t^{(k)}+\\alpha(D\\operatorname{Re}(s_t^{(k)})-F_t),\\ \\forall t\\in N_T, \\quad (11)\n\\omega_t^{(k+1)}=\\omega_t^{(k)}+\\alpha\\left(-1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{V}{V_0}\\right),\\ \\forall t\\in N_T, \\quad (12)\nR_t^{(k+1)}=D^T\\lambda_t^{(k+1)}+\\frac{\\operatorname{Re}(Z^T)}{V_0^2}\\omega_t^{(k+1)},\\ \\forall t\\in N_T. \\quad (13)\nIn (11) and (12), \\alpha represents a proper step size, and the term after \\alpha is the residual of constraints (7) and (8), respectively. The justification of (11)-(13) will be discussed in Section III-B by a metaphor based on the control theory. There is an implicit requirement for the marginal prices \\lambda_t and \\omega_t, i.e., they must be nonnegative; therefore, they are modified by,","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R003","quote":"Then, \\lambda_t, \\omega_t and R_t can be updated by,\n\\lambda_t^{(k+1)}=\\lambda_t^{(k)}+\\alpha(D\\operatorname{Re}(s_t^{(k)})-F_t),\\ \\forall t\\in N_T, \\quad (11)\n\\omega_t^{(k+1)}=\\omega_t^{(k)}+\\alpha\\left(-1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{V}{V_0}\\right),\\ \\forall t\\in N_T, \\quad (12)\nR_t^{(k+1)}=D^T\\lambda_t^{(k+1)}+\\frac{\\operatorname{Re}(Z^T)}{V_0^2}\\omega_t^{(k+1)},\\ \\forall t\\in N_T. \\quad (13)\nIn (11) and (12), \\alpha represents a proper step size, and the term after \\alpha is the residual of constraints (7) and (8), respectively. The justification of (11)-(13) will be discussed in Section III-B by a metaphor based on the control theory. There is an implicit requirement for the marginal prices \\lambda_t and \\omega_t, i.e., they must be nonnegative; therefore, they are modified by,"},{"evidence_id":"v141-b-g02-e016","location":{"location_id":"src-c263a83472-p05-c2r3__v141-a-M02-coordination","page":5,"printed_page":null,"section":"III-B. Control Diagram of the Iteration Process","anchor_text":"proﬁles. Then, the power ﬂows are sent to the power ﬂow 4) controller (upper part of the diagram), a","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"After gathering the planning results from the aggregators, the DSO performs load flow analysis and determines the network status, including line flows and voltage profiles. Then, the power flows are sent to the power flow controller (upper part of the diagram), and the voltage profiles are sent to the voltage controller (lower part of the diagram). The received signals (flows and voltages) are compared with the references respectively, and then the error signals are multiplied by the step size \\alpha. Then the signals enter two integrators, which are corresponding to (11) and (12), respectively. Afterwards, two limiters force the signals to be nonnegative, which are corresponding to (14) and (15), respectively. Then the signals (marginal prices for line flow and voltage respectively) are transformed to DPTs by the matrix D^T and matrix \\operatorname{Re}(Z^T)/V_0^2, respectively.","paper":"39-dynamic_congestion_tariff","rule_id":"v141-c-R003","quote":"After gathering the planning results from the aggregators, the DSO performs load flow analysis and determines the network status, including line flows and voltage profiles. Then, the power flows are sent to the power flow controller (upper part of the diagram), and the voltage profiles are sent to the voltage controller (lower part of the diagram). The received signals (flows and voltages) are compared with the references respectively, and then the error signals are multiplied by the step size \\alpha. Then the signals enter two integrators, which are corresponding to (11) and (12), respectively. Afterwards, two limiters force the signals to be nonnegative, which are corresponding to (14) and (15), respectively. Then the signals (marginal prices for line flow and voltage respectively) are transformed to DPTs by the matrix D^T and matrix \\operatorname{Re}(Z^T)/V_0^2, respectively."}],"candidate_only":true,"classification_subtypes":["aggregated_demand_quantity_submission","chosen_consumption_submission","separate_demand_quantity_submission"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"KG40-L3-SC-L3-e11e47541452e26e","secondary_families":[],"stage":"L3","ontological_kind":"SC-L3-e11e47541452e26e"},"semantic_definition":{"definition":"Participants or their aggregation agents report to the organizer the quantity of consumption demand formed by autonomous choice or local dispatch; separate declaration, aggregation mapping, and provisional updates are retained according to source.","identity_fields":["Submitter: the decision-maker for consumption arrangements or its aggregation agent.","Object: the quantity of consumption demand not offset by generation.","Function: disclose the consumption-side quantity decision to the organizer."]},"source_units":[{"unit_id":"11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","paper_id":"11-p2p_mechanisms_evaluation","mechanism_id":"v141-a-M02","function":"bidding.demand","source_occurrences":[{"id":"11-p2p_mechanisms_evaluation::v141-c-R011::V::bidding.demand","rule_id":"v141-c-R011","market_meaning":"Each energy bid must report demand separately from generation at every time step, rather than reporting only overall net demand. Scope: Demand information in each participant's MMR energy bid.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Demand information in each participant's MMR energy bid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-ev-06"]},"constraint_refs":["11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C001","11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C002"],"decision_anchor":"bidding.demand","source_rule_sha256":"f2f5ee8b3a4400520c812e369521b99a6c756ae509e728e1811dfd4a5dd2ae07"},{"id":"11-p2p_mechanisms_evaluation::v141-c-R014::V::bidding.demand","rule_id":"v141-c-R014","market_meaning":"Submitted generation quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. Submitted demand quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. The coordinator calculates internal prices using the MMR pricing model. Scope: MMR pricing within one energy sharing region. The internal buying and selling prices are equal to the arithmetic mean of the retailer's export and retail prices. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation equals total demand. The internal selling price remains the arithmetic mean of export and retail prices; the internal buying price is adjusted to cover the regional deficit imported at the retailer's retail price. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation is less than total demand. The internal buying price remains the arithmetic mean of export and retail prices; the internal selling price is adjusted to incorporate surplus-export income for distribution among participants providing electricity through generation or EV discharging. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation exceeds total demand.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"MMR internal prices at a given time step within one energy sharing region. | MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. | MMR pricing within one energy sharing region.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},"constraint_refs":["11-p2p_mechanisms_evaluation::v141-c-R014::v141-c-R014-C002"],"decision_anchor":"pricing.local","source_rule_sha256":"a224bf63fdbdff5bed026ae7e29a057b5ec0c0bbb01e1bf9b93de0d872bafc47"}],"constraints":[{"constraint_id":"v141-c-R011-C001","kind":"procedural","role":"core","statement":"Each energy bid must report demand separately from generation at every time step, rather than reporting only overall net demand. Scope: Demand information in each participant's MMR energy bid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-ev-06"],"ref":"11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C001","source_rule_id":"v141-c-R011","evidence":[{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"}]},{"constraint_id":"v141-c-R011-C002","kind":"mathematical","role":"core","statement":"The demand component of the MMR energy bid at time step t is defined by e_{dem,t}^{bid} = (sum over flexible appliances δ in A_f of x_{δ,t}^*) + (x_t^{ch*}/η^{ch} + P_t^{must-run}), for t in T; this demand component is reported separately from the generation component.","expression":"e_{dem}^{bid} = \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["v141-c-R011-x-dem-bid-t","v141-c-R011-x-delta-t-star","v141-c-R011-x-ch-t-star"],"parameter_refs":["v141-c-R011-theta-eta-ch","v141-c-R011-theta-P-must-run-t"],"evidence_ids":["v141-b-g07-ev-06"],"ref":"11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C002","source_rule_id":"v141-c-R011","evidence":[{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"}]},{"constraint_id":"v141-c-R014-C002","kind":"procedural","role":"core","statement":"Submitted demand quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","pricing.local"],"variable_refs":[],"parameter_refs":["e_dem_bid_nt"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"ref":"11-p2p_mechanisms_evaluation::v141-c-R014::v141-c-R014-C002","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"},{"evidence_id":"v141-b-g07-ev-07","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-pricing","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A25-A27","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region. If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:\n\np_t^{buy} = p_t^{sell} = r_t^{average} = \\frac{(r_t^{export} + r_t^{retail})}{2}, \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| = \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A25)\n\nIf the generation is less than demand, the deficit generation has to be supplied by the power imported from the retailer at the retail price, and the cost of this import should be covered. Therefore, in this situation, the internal selling price keeps the same as that in Formula (A25), but the buying price is modified:\n\n\\begin{cases} p_t^{buy} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\right) \\cdot r_t^{retail}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}} \\\\ p_t^{sell} = r_t^{average} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \u003c \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A26)\n\nSimilarly, if the generation is higher than demand, the surplus generation needs to be sold to the retailer at the export price, and this part of income needs to be distributed among all the prosumers who provide electricity by generation or EV discharging. The internal price is calculated as follows:\n\n\\begin{cases} p_t^{buy} = r_t^{average} \\\\ p_t^{sell} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\right) \\cdot r_t^{export}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}|} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| > \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A27)\n\nFormulas (A25)-(A27) compose the pricing model in the coordinator agent under mid-market rate mechanism."}]}],"variables":[{"variable_id":"v141-c-R011-x-dem-bid-t","symbol":"e_{dem,t}^{bid}","meaning":"Demand component of the MMR energy bid submitted by a prosumer at time step t; source formula (A24) defines it as the sum of optimal flexible-appliance power plus EV charging power divided by charging efficiency plus inflexible must-run demand.","kind":"operational","domain":"Time-indexed demand component of an MMR energy bid, for t in the scheduling horizon T.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-06"],"source_rule_id":"v141-c-R011","declaration_ref":"11-p2p_mechanisms_evaluation::v141-c-R011::x::v141-c-R011-x-dem-bid-t"},{"variable_id":"v141-c-R011-x-delta-t-star","symbol":"x_{\\delta,t}^*","meaning":"Optimal power of flexible appliance δ at time step t from the prosumer decision-making model, used as the first term in the MMR demand-bid component.","kind":"operational","domain":"Power of flexible appliance δ at time step t, for δ in the flexible-appliance set A_f and t in T, as prescribed by the decision-making model.","unit":null,"indices":["δ","t"],"evidence_ids":["v141-b-g07-ev-06"],"source_rule_id":"v141-c-R011","declaration_ref":"11-p2p_mechanisms_evaluation::v141-c-R011::x::v141-c-R011-x-delta-t-star"},{"variable_id":"v141-c-R011-x-ch-t-star","symbol":"x_t^{ch*}","meaning":"Optimal EV charging power at time step t from the prosumer decision-making model, divided by charging efficiency in the MMR demand-bid component.","kind":"operational","domain":"EV charging power at time step t, for t in T, as prescribed by the decision-making model.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-06"],"source_rule_id":"v141-c-R011","declaration_ref":"11-p2p_mechanisms_evaluation::v141-c-R011::x::v141-c-R011-x-ch-t-star"}],"parameters":[{"parameter_id":"v141-c-R011-theta-eta-ch","symbol":"\\eta^{ch}","meaning":"Charging efficiency of the electric vehicle; source formula (A24) divides EV charging power by this efficiency in the demand-bid component.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g07-ev-06"],"source_rule_id":"v141-c-R011","declaration_ref":"11-p2p_mechanisms_evaluation::v141-c-R011::theta::v141-c-R011-theta-eta-ch"},{"parameter_id":"v141-c-R011-theta-P-must-run-t","symbol":"P_t^{must-run}","meaning":"Inflexible must-run demand at time step t included in the MMR demand-bid component.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-06"],"source_rule_id":"v141-c-R011","declaration_ref":"11-p2p_mechanisms_evaluation::v141-c-R011::theta::v141-c-R011-theta-P-must-run-t"},{"parameter_id":"e_dem_bid_nt","symbol":"e_{dem,n,t}^{bid}","meaning":"Demand-component energy bid submitted by prosumer n at time step t under MMR; an exogenous input to this pricing rule, entering the internal-price formulas through the regional total Σ_{n∈PA} e_{dem,n,t}^{bid}. Scoped here as pricing input, not as a decision of pricing.local.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n","t"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"source_rule_id":"v141-c-R014","declaration_ref":"11-p2p_mechanisms_evaluation::v141-c-R014::theta::e_dem_bid_nt"}]},{"unit_id":"14-stackelberg_pv_sharing::v141-a-M01::bidding.demand","paper_id":"14-stackelberg_pv_sharing","mechanism_id":"v141-a-M01","function":"bidding.demand","source_occurrences":[{"id":"14-stackelberg_pv_sharing::v141-c-R001::V::bidding.demand","rule_id":"v141-c-R001","market_meaning":"Broadcasting the next-slot internal prices precedes submission of the prosumers' chosen next-slot consumption quantities to MGO. Scope: The numbered next-slot ESM scheduling procedure within the microgrid, including every participating prosumer's submission of optimal consumption.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"The numbered next-slot ESM scheduling procedure within the microgrid, including every participating prosumer's submission of optimal consumption.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E04"]},"constraint_refs":["14-stackelberg_pv_sharing::v141-c-R001::v141-c-R001-C001"],"decision_anchor":"bidding.demand","source_rule_sha256":"78439c26a391aea634b0125d8afaefe59b64ce9bb17a0ea1f43443bf48d0e0d2"},{"id":"14-stackelberg_pv_sharing::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"Each prosumer submits its chosen next-slot energy-consumption quantity x_n^o to the MGO. Scope: Hour-ahead ESM within the microgrid; submission of each prosumer's chosen total consumption for the next time slot. The MGO is obligated to pursue maximization of its own profit when coordinating PV energy sharing. Scope: The MGO's objective in the Stackelberg energy-sharing arrangement. The MGO is required to trade with the utility grid to balance supplies and demands. Scope: The microgrid operator's external balancing duty under ESM. Condition: An internal mismatch occurs between PV power generation and load power demand. A server should be deployed in the MGO. Scope: Infrastructure at the MGO for implementing ESM. Condition: Implementation of the ESM.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Hour-ahead ESM within the microgrid; submission of each prosumer's chosen total consumption for the next time slot. | Infrastructure at the MGO for implementing ESM. | The MGO's objective in the Stackelberg energy-sharing arrangement. | The microgrid operator's external balancing duty under ESM.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e001","v141-b-g01-e005","v141-b-g01-e020","v141-b-g01-e021"]},"constraint_refs":["14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C001","14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C005"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"0d8e892f31e0d5302dacb59afdc173bdc4228ba3a65407577a9a7b02d7bb6d8a"}],"constraints":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"Broadcasting the next-slot internal prices precedes submission of the prosumers' chosen next-slot consumption quantities to MGO. Scope: The numbered next-slot ESM scheduling procedure within the microgrid, including every participating prosumer's submission of optimal consumption.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E04"],"ref":"14-stackelberg_pv_sharing::v141-c-R001::v141-c-R001-C001","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-E04","location":{"location_id":"src-ed046424ff-p04-c2r2__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.C Implementation Process","anchor_text":"n- set as λs and λb, respectively. 2) Every prosumer submits ˆEgn, kn, and the role of buyer or re s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"3) Considering (26) and (27) belong to nonlinear programming problem, the MGO can solve (30) and obtain the internal prices p_{s} and p_{b} for the next time slot by using interior point method. 4) The MGO broadcasts the internal prices of next time slot to all the prosumers; 5) Each prosumer evaluates the flexible load of the next time slot, and decides the optimal energy consumption x_{o}^{n}. 6) Every prosumer sends x_{o}^{n} to the MGO, the energy sharing of the next time slot is decided."}]},{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Each prosumer submits its chosen next-slot energy-consumption quantity x_n^o to the MGO. Scope: Hour-ahead ESM within the microgrid; submission of each prosumer's chosen total consumption for the next time slot.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":["v141-c-R003-x001"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e020"],"ref":"14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C001","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-e020","location":{"location_id":"src-ed046424ff-p04-c2r2__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.C Implementation Process","anchor_text":"n- set as λs and λb, respectively. 2) Every prosumer submits ˆEgn, kn, and the role of buyer or re s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Each prosumer evaluates the flexible load of the next time slot, and decides the optimal energy consumption x_n^o. Every prosumer sends x_n^o to the MGO, the energy sharing of the next time slot is decided."}]},{"constraint_id":"v141-c-R003-C005","kind":"procedural","role":"supporting","statement":"The prosumers in set G act as followers and choose their optimal consumption in response to the internal prices set by the MGO, the leader of the game. Scope: Stackelberg leader-follower coordination in the ESM arrangement.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":["v141-c-R003-x001"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e015","v141-b-g01-e006"],"ref":"14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C005","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-e015","location":{"location_id":"src-ed046424ff-p04-c1r1__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.A Formulation of Stackelberg Game","anchor_text":"LIU et al.: ENERGY SHARING MANAGEMENT FOR MICROGRIDS WITH PV PROSUM by changing their energy consump","equation_id":"(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The game is formally defined by its strategic form as L = {(G ∪ {MGO}), {X_n}_{n∈G}, {P_b}, {P_s}, {U_n}_{n∈G}, R} (6) which consists of the following components: 1) The prosumers in set G act as followers and choose their optimal consumption in response to the internal prices set by the MGO, the leader of the game. 2) X_n is the set of strategies of prosumer n, which is constrained by x_n^min ≤ x_n ≤ x_n^max. 3) P_b and P_s are the sets of strategies set by MGO, which are the vectors of the internal prices p_b and p_s, respectively. It should be ensured that the internal prices are constrained by λ^s ≤ p_s \u003c p_b ≤ λ^b_n. 4) U_n is the utility function of prosumer n, as shown in (1) that captures the prosumer's benefit from consuming energy x_n and sharing energy E_n^g − x_n with other prosumers in the microgrid. 5) R is the profit function of MGO, as shown in (5) that captures the total profit incurred by the sharing energy inside the microgrid and trading with the utility grid."},{"evidence_id":"v141-b-g01-e006","location":{"location_id":"src-ed046424ff-p02-c1r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. INTRODUCTION","anchor_text":"g p p mentioned studies, two main differences have been made. The as ﬁrst is the role of participant","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"unknown"},"source_text":"In this paper, every prosumer has equal privilege which means prosumers are participated in the microgrid operation equipotently. Thus, we select MGO as the leader, which means that the MGO determines the buying and selling prices simultaneously. And the prosumers act as followers to adjust their energy consumption behaviors according to the time-varying prices."}]}],"variables":[{"variable_id":"v141-c-R003-x001","symbol":"x_n^o","meaning":"Optimal/chosen energy consumption of prosumer n for the next time slot, submitted to the MGO.","kind":"operational","domain":"Energy-consumption quantity for prosumer n in the next time slot; the cited passage does not state numerical bounds for x_n^o, while the underlying consumption decision is bounded by x_n^min ≤ x_n ≤ x_n^max.","unit":null,"indices":["n"],"evidence_ids":["v141-b-g01-e020","v141-b-g01-e015"],"source_rule_id":"v141-c-R003","declaration_ref":"14-stackelberg_pv_sharing::v141-c-R003::x::v141-c-R003-x001"}],"parameters":[]},{"unit_id":"39-dynamic_congestion_tariff::v141-a-M02::bidding.demand","paper_id":"39-dynamic_congestion_tariff","mechanism_id":"v141-a-M02","function":"bidding.demand","source_occurrences":[{"id":"39-dynamic_congestion_tariff::v141-c-R001::V::bidding.demand","rule_id":"v141-c-R001","market_meaning":"DPT price signals guide aggregators' updates of the demand quantities represented by their tentative purchasing plans, whose results are returned to the DSO as demand responses. Scope: Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. Condition: Within the iterative process, using the DPT signals received for the current planning update. Each aggregator's tentative purchasing quantities are planned to minimize energy cost plus network tariff cost, subject to EV operating limits, household thermal limits and HP input-power limits. Scope: Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands. Condition: During the DPT iterative planning process.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. | Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e004","v141-b-g02-e015","v141-b-g13-E13","v141-b-g19-E19"]},"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C001","39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C002","39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C003"],"decision_anchor":"bidding.demand","source_rule_sha256":"9b8e778b4854afd0b41ecd058db42873ffec108c38fd9de44e37a205a86ffd4a"},{"id":"39-dynamic_congestion_tariff::v141-c-R002::V::bidding.demand","rule_id":"v141-c-R002","market_meaning":"Aggregators submit their tentative demand plans to the DSO. Scope: DPT distributed congestion-management iterations between aggregators and the DSO. The DSO-side formulation checks network limits without a DSO-side optimization model. Scope: DSO-side formulation of DPT congestion management. The DSO needs to forecast conventional active and reactive power consumption at each load point; it need not forecast price sensitivities or flexible demands for the DPT method. Scope: DSO forecasting responsibilities under the DPT method.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"DPT distributed congestion-management iterations between aggregators and the DSO. | DSO forecasting responsibilities under the DPT method. | DSO-side formulation of DPT congestion management.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e025","v141-b-g13-E13","v141-b-g21-E21"]},"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R002::v141-c-R002-C001"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"3abc1bfafb81e0f5da3f20b028060962f71b9a9fd8ae8b1909761c869abdca1d"},{"id":"39-dynamic_congestion_tariff::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"Tentative demand-response submissions provide the information used to identify congestion and modify DPT coordination signals accordingly. Scope: Iterative DPT congestion-management planning between aggregators and the DSO. DPT coordination determines a rate for each load bus and time period according to network conditions and forecast nonflexible load, with the objective that aggregator energy schedules respect network limits. Scope: DPT rate determination for distribution-network congestion-management planning. The tentative DPT signals are initialized to zero. Scope: Initialization of the iterative DPT coordination procedure. Condition: At initiation of the iterative process. The DPT coordination process continues iterating until network constraints are satisfied and final DPT rates are determined. Scope: Continuation and termination of iterative DPT coordination. The line-flow and voltage marginal-price signals are constrained to be nonnegative before transformation into DPTs. Scope: Internal signal restrictions in iterative DPT calculation. The final DPT rates equal the last iteration DPT rates. Scope: Finalization of iterative DPT signals. Condition: When the DPT iteration converges.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Continuation and termination of iterative DPT coordination. | DPT rate determination for distribution-network congestion-management planning. | Finalization of iterative DPT signals. | Initialization of the iterative DPT coordination procedure. | Internal signal restrictions in iterative DPT calculation. | Iterative DPT congestion-management planning between aggregators and the DSO.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e013","v141-b-g02-e016","v141-b-g12-E12","v141-b-g13-E13"]},"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C001","39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C007"],"decision_anchor":"coordination.price_signal","source_rule_sha256":"6a53d1884a87227f2824a56d42c5278649a7c6a0e0e98b1d2694e6249181d473"}],"constraints":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"DPT price signals guide aggregators' updates of the demand quantities represented by their tentative purchasing plans, whose results are returned to the DSO as demand responses. Scope: Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. Condition: Within the iterative process, using the DPT signals received for the current planning update.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e015","v141-b-g13-E13"],"ref":"39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C001","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-e015","location":{"location_id":"src-c263a83472-p05-c1r4__v141-a-M02-coordination","page":5,"printed_page":null,"section":"III-B. Control Diagram of the Iteration Process","anchor_text":"g g p only be employed to calculate DT rates, but not the DPT rates. pa In Section III-B, the margin","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"From the DSO point of view, the price-based congestion management process is an indirect control process. The aggregators respond to the price signals from the DSO (e.g., DT or DPT), and the DSO can adjust the price signals such that the responses from the aggregators can respect the network limits. The control framework of the whole congestion management process is shown in Fig. 3. The target system comprises of the distribution network and two actors, i.e., the DSO and aggregators. The aggregators receive the DPTs and make their own optimal planning (DR). Then, the planning results are sent to the DSO."},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."}]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"Each aggregator's tentative purchasing quantities are planned to minimize energy cost plus network tariff cost, subject to EV operating limits, household thermal limits and HP input-power limits. Scope: Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands. Condition: During the DPT iterative planning process.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e004","v141-b-g13-E13","v141-b-g19-E19"],"ref":"39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C002","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-e004","location":{"location_id":"src-c263a83472-p04-c2r1__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"NETWORKS 2151 concept. The optimal planning problem for aggregator i is formulated as (1)-(5). min p","equation_id":"(1)-(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"An aggregator can use a quadratic function to represent the total cost including energy consumption and network tariff as shown in (1). The quadratic term in (1) is due to the DPT received from the DSO (R_t is the DPT; therefore, it is a fixed parameter for the optimizations at the aggregator side). The optimal planning problem for aggregator i is formulated as (1)-(5). \\min_{p_{i,t},\\hat p_{i,t}} \\sum_{t\\in N_T}(p_{i,t}+\\hat p_{i,t})^T E_i^T R_t E_i(p_{i,t}+\\hat p_{i,t}) + \\sum_{t\\in N_T}(c_t^1)^T(p_{i,t}+\\hat p_{i,t}) \\quad (1)"},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."},{"evidence_id":"v141-b-g19-E19","location":{"location_id":"src-c263a83472-p04-c2r2__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"t_≤t (2) pmini,t ≤pi,t ≤pmaxi,t ∀t ∈NT, (3) a- Ka,mini,t ≤ Ai,t,t_ˆpi,t_ + ui,t ≤Ka,maxi,t , ∀t ∈NT,","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Constraints (2) - (3) are from the limits of EVs. Constraint (4) represents the thermal limits of households and (5) gives the input power limits of HPs. Constraint (4) is derived from the thermal process analysis of the household and the HP as shown in [4]."}]},{"constraint_id":"v141-c-R001-C003","kind":"mathematical","role":"core","statement":"After solving its optimal planning problem, aggregator i forms the aggregated demand response sent to the DSO as the load-bus mapping of its total EV charging and HP power consumption: p_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}) for all t in N_t.","expression":"p_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}),\\quad \\forall t\\in N_t \\tag{6}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["x-p-it","x-phat-it","x-pa-it"],"parameter_refs":["theta-Ei"],"evidence_ids":["v141-b-g02-e006","v141-b-g20-E20"],"ref":"39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C003","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-e006","location":{"location_id":"src-c263a83472-p04-c2r2__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"t_≤t (2) pmini,t ≤pi,t ≤pmaxi,t ∀t ∈NT, (3) a- Ka,mini,t ≤ Ai,t,t_ˆpi,t_ + ui,t ≤Ka,maxi,t , ∀t ∈NT,","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After solving the optimal problem, the aggregator i will have a tentative optimal plan (p^*_{i,t}, \\hat p^*_{i,t}). Then (6) can be used to formulate the aggregated DR for aggregator i, which will be sent to the DSO.\np_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}), \\forall t\\in N_t \\quad (6)"},{"evidence_id":"v141-b-g20-E20","location":{"location_id":"src-c263a83472-p04-c2r3__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.2) Formulation at the DSO Side","anchor_text":"ent pai,t = Ei pi,t + ˆpi,t , ∀t ∈Nt (6) he 2) Formulation at the DSO Side: At the DSO side, there i","equation_id":"(6)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After solving the optimal problem, the aggregator \\(i\\) will have a tentative optimal plan \\((p_{i,t}^*,\\hat p_{i,t}^*)\\). Then (6) can be used to formulate the aggregated DR for aggregator \\(i\\), which will be sent to the DSO. \\[p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}),\\quad \\forall t\\in N_t \\tag{6}\\]"}]},{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"Aggregators submit their tentative demand plans to the DSO. Scope: DPT distributed congestion-management iterations between aggregators and the DSO.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g13-E13"],"ref":"39-dynamic_congestion_tariff::v141-c-R002::v141-c-R002-C001","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."}]},{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Tentative demand-response submissions provide the information used to identify congestion and modify DPT coordination signals accordingly. Scope: Iterative DPT congestion-management planning between aggregators and the DSO.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g13-E13"],"ref":"39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C001","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."}]},{"constraint_id":"v141-c-R003-C007","kind":"mathematical","role":"core","statement":"During DPT coordination, the line-flow marginal-price signal, voltage marginal-price signal, and DPT-rate matrix are updated from the network residuals using the step size and the DPT transformation matrices, for every time period.","expression":"\\lambda_t^{(k+1)}=\\lambda_t^{(k)}+\\alpha\\left(D\\operatorname{Re}(s_t^{(k)})-F_t\\right),\\quad \\omega_t^{(k+1)}=\\omega_t^{(k)}+\\alpha\\left(-1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{\\underline V}{V_0}\\right),\\quad R_t^{(k+1)}=D^T\\lambda_t^{(k+1)}+\\frac{\\operatorname{Re}(Z^T)}{V_0^2}\\omega_t^{(k+1)},\\quad \\forall t\\in N_T","formalization_origin":"source","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002","v141-c-R003-X003","v141-c-R003-X004"],"parameter_refs":["v141-c-R003-P001","v141-c-R003-P003","v141-c-R003-P004","v141-c-R003-P005","v141-c-R003-P006","v141-c-R003-P007"],"evidence_ids":["v141-b-g02-e011","v141-b-g02-e016"],"ref":"39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C007","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g02-e011","location":{"location_id":"src-c263a83472-p05-c1r2__v141-a-M02-pricing","page":5,"printed_page":null,"section":"III-A. Mathematical Formulation of DPT Method","anchor_text":"t ) t Then, λt, ωt and Rt can be updated by, λ(k+1)t = λ(k)t + α DRe s(k)t −Ft , ∀t ∈NT, (11) 1 V ω(","equation_id":"(11)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Then, \\lambda_t, \\omega_t and R_t can be updated by,\n\\lambda_t^{(k+1)}=\\lambda_t^{(k)}+\\alpha(D\\operatorname{Re}(s_t^{(k)})-F_t),\\ \\forall t\\in N_T, \\quad (11)\n\\omega_t^{(k+1)}=\\omega_t^{(k)}+\\alpha\\left(-1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{V}{V_0}\\right),\\ \\forall t\\in N_T, \\quad (12)\nR_t^{(k+1)}=D^T\\lambda_t^{(k+1)}+\\frac{\\operatorname{Re}(Z^T)}{V_0^2}\\omega_t^{(k+1)},\\ \\forall t\\in N_T. \\quad (13)\nIn (11) and (12), \\alpha represents a proper step size, and the term after \\alpha is the residual of constraints (7) and (8), respectively. The justification of (11)-(13) will be discussed in Section III-B by a metaphor based on the control theory. There is an implicit requirement for the marginal prices \\lambda_t and \\omega_t, i.e., they must be nonnegative; therefore, they are modified by,"},{"evidence_id":"v141-b-g02-e016","location":{"location_id":"src-c263a83472-p05-c2r3__v141-a-M02-coordination","page":5,"printed_page":null,"section":"III-B. Control Diagram of the Iteration Process","anchor_text":"proﬁles. Then, the power ﬂows are sent to the power ﬂow 4) controller (upper part of the diagram), a","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"After gathering the planning results from the aggregators, the DSO performs load flow analysis and determines the network status, including line flows and voltage profiles. Then, the power flows are sent to the power flow controller (upper part of the diagram), and the voltage profiles are sent to the voltage controller (lower part of the diagram). The received signals (flows and voltages) are compared with the references respectively, and then the error signals are multiplied by the step size \\alpha. Then the signals enter two integrators, which are corresponding to (11) and (12), respectively. Afterwards, two limiters force the signals to be nonnegative, which are corresponding to (14) and (15), respectively. Then the signals (marginal prices for line flow and voltage respectively) are transformed to DPTs by the matrix D^T and matrix \\operatorname{Re}(Z^T)/V_0^2, respectively."}]}],"variables":[{"variable_id":"x-p-it","symbol":"p_{i,t}","meaning":"Charging power of EVs of aggregator i at planning period t; one component of the aggregator's tentative purchasing-plan quantities and of the demand response submitted through (6).","kind":"operational","domain":"Real-valued EV charging power schedule over i in N_B and t in N_t; the source optimization bounds it by (3).","unit":null,"indices":["i in N_B","t in N_t"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e006","v141-b-g20-E20"],"source_rule_id":"v141-c-R001","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R001::x::x-p-it"},{"variable_id":"x-phat-it","symbol":"\\hat p_{i,t}","meaning":"Power consumption of HPs of aggregator i at planning period t; one component of the aggregator's tentative purchasing-plan quantities and of the demand response submitted through (6).","kind":"operational","domain":"Real-valued HP power-consumption schedule over i in N_B and t in N_t; the source optimization bounds it by (5).","unit":null,"indices":["i in N_B","t in N_t"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e006","v141-b-g20-E20"],"source_rule_id":"v141-c-R001","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R001::x::x-phat-it"},{"variable_id":"x-pa-it","symbol":"p_{i,t}^a","meaning":"Aggregated demand response formed by aggregator i and sent to the DSO, defined in (6) as the load-bus mapping of the aggregator's total EV charging plus HP power consumption.","kind":"operational","domain":"Real-valued aggregated demand response at load buses over i in N_B and t in N_t, determined by (6).","unit":null,"indices":["i in N_B","t in N_t"],"evidence_ids":["v141-b-g02-e006","v141-b-g20-E20"],"source_rule_id":"v141-c-R001","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R001::x::x-pa-it"},{"variable_id":"v141-c-R003-X001","symbol":"\\lambda_t","meaning":"Line-flow marginal-price signal vector used and updated in the iterative DPT coordination loop.","kind":"operational","domain":"\\mathbb{R}^{N_L}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::x::v141-c-R003-X001"},{"variable_id":"v141-c-R003-X002","symbol":"\\omega_t","meaning":"Voltage marginal-price signal vector used and updated in the iterative DPT coordination loop.","kind":"operational","domain":"\\mathbb{R}^{N_d}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::x::v141-c-R003-X002"},{"variable_id":"v141-c-R003-X003","symbol":"R_t","meaning":"Matrix form of the DPT rates determined iteratively by the DSO at each coordination iteration.","kind":"operational","domain":"\\mathbb{R}^{N_d\\times N_d}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e011","v141-b-g16-E16"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::x::v141-c-R003-X003"},{"variable_id":"v141-c-R003-X004","symbol":"s_t","meaning":"Total apparent power load at each load point, determined from aggregator demand responses and conventional load in the DPT iteration.","kind":"operational","domain":"\\mathbb{C}^{N_d}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e009","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::x::v141-c-R003-X004"}],"parameters":[{"parameter_id":"theta-Ei","symbol":"E_i","meaning":"Customer-to-load-bus mapping matrix used in (6) to map aggregator EV and HP power into load-bus demand response.","value":{"kind":"symbolic","number_value":null,"text_value":"customer-to-load-bus mapping matrix"},"unit":null,"indices":["i in N_B"],"evidence_ids":["v141-b-g02-E02","v141-b-g20-E20"],"source_rule_id":"v141-c-R001","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R001::theta::theta-Ei"},{"parameter_id":"v141-c-R003-P001","symbol":"\\alpha","meaning":"Step size used in the DPT signal update equations.","value":{"kind":"symbolic","number_value":null,"text_value":"proper step size"},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::theta::v141-c-R003-P001"},{"parameter_id":"v141-c-R003-P003","symbol":"D","meaning":"Power transfer distribution factor (PTDF) matrix used in line-flow checks and in the DPT transformation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::theta::v141-c-R003-P003"},{"parameter_id":"v141-c-R003-P004","symbol":"F_t","meaning":"Line loading limit of active power used in the line-flow residual of the DPT update.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t∈N_T"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e007","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::theta::v141-c-R003-P004"},{"parameter_id":"v141-c-R003-P005","symbol":"Z","meaning":"Inverse matrix of the partial nodal admittance matrix Y_{LL}, used in the voltage residual and voltage-signal transformation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03","v141-b-g02-e018","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::theta::v141-c-R003-P005"},{"parameter_id":"v141-c-R003-P006","symbol":"V_0","meaning":"Voltage at node 0 used in the voltage residual and voltage-signal transformation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::theta::v141-c-R003-P006"},{"parameter_id":"v141-c-R003-P007","symbol":"\\underline V","meaning":"Lower voltage limit used in the voltage residual of the DPT update.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e011"],"source_rule_id":"v141-c-R003","declaration_ref":"39-dynamic_congestion_tariff::v141-c-R003::theta::v141-c-R003-P007"}]}],"source_definitions":[{"unit_id":"11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","stage":"L3","subtype":"separate_demand_quantity_submission","projection_status":"clear","target_definition":"Demand and generation components are submitted separately for each time period; the demand declaration is e_{dem,t}^bid=Σ_{δ∈A_f}x_{δ,t}*+x_t^{ch*}/η^{ch}+P_t^{must-run}, and it is not permitted to report only the total net demand after offsetting generation.","form_kind":"mathematical","identity_fields":["Object: the demand electricity quantity series listed separately from generation.","Core relationship: independently report the demand component.","Output: e_{dem,t}^bid."],"variation_fields":["Demand consists of the optimal power of flexible appliances, efficiency-adjusted EV charging power, and must-run load.","Submitted period by period over the dispatch horizon T.","The demand declaration serves as an exogenous input to regional aggregate pricing."],"constraint_refs":["11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C001","11-p2p_mechanisms_evaluation::v141-c-R011::v141-c-R011-C002","11-p2p_mechanisms_evaluation::v141-c-R014::v141-c-R014-C002"],"paper_id":"11-p2p_mechanisms_evaluation","mechanism_id":"v141-a-M02","function":"bidding.demand","template_code":"PGR"},{"unit_id":"14-stackelberg_pv_sharing::v141-a-M01::bidding.demand","stage":"L3","subtype":"chosen_consumption_submission","projection_status":"clear","target_definition":"After each prosumer receives the internal price for the next time slot, it autonomously selects the consumption quantity x_n^o and submits this consumption quantity to the MGO.","form_kind":"procedural","identity_fields":["Object: the consumption quantity selected by the participant.","Core operation: submit the consumption decision to the organizer.","Output: per-participant consumption quantity information x_n^o."],"variation_fields":["The submitter is the PV prosumer and the receiver is the MGO.","Hourly advance scheduling; submission occurs after price broadcasting and flexible-load evaluation.","The underlying consumption strategy has the bounds x_n^min≤x_n≤x_n^max."],"constraint_refs":["14-stackelberg_pv_sharing::v141-c-R001::v141-c-R001-C001","14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C001","14-stackelberg_pv_sharing::v141-c-R003::v141-c-R003-C005"],"paper_id":"14-stackelberg_pv_sharing","mechanism_id":"v141-a-M01","function":"bidding.demand","template_code":"PGR"},{"unit_id":"39-dynamic_congestion_tariff::v141-a-M02::bidding.demand","stage":"L3","subtype":"aggregated_demand_quantity_submission","projection_status":"clear","target_definition":"The aggregator maps the current-round locally optimal electricity consumption plan to load-bus demand response and submits it to the DSO: p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}), ∀t∈N_t; the submitted object is the provisional demand quantity.","form_kind":"mathematical","identity_fields":["Object: time-differentiated and location-differentiated provisional demand quantity.","Core relationship: the local electricity consumption plan is mapped through aggregation to form demand response and is reported to the coordinator.","Output: the submitted aggregated demand plan."],"variation_fields":["The submitting party is the aggregator and the receiving party is the DSO.","Demand consists of EV charging power p_{i,t} and HP power \\hat p_{i,t}; E_i is the mapping from customers to load buses.","Given the current-round DPT, the local plan minimizes the sum of electricity cost and network charges.","The local plan is subject to EV operation, household thermal conditions, and HP input power limits.","Demand is updated in DPT iterations and used for subsequent congestion identification."],"constraint_refs":["39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C002","39-dynamic_congestion_tariff::v141-c-R001::v141-c-R001-C003","39-dynamic_congestion_tariff::v141-c-R002::v141-c-R002-C001","39-dynamic_congestion_tariff::v141-c-R003::v141-c-R003-C001"],"paper_id":"39-dynamic_congestion_tariff","mechanism_id":"v141-a-M02","function":"bidding.demand","template_code":"PGR"}],"source_variants":[{"unit_id":"11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","retained_variants":["e_{dem,t}^bid=Σ_{δ∈A_f}x_{δ,t}*+x_t^{ch*}/η^{ch}+P_t^{must-run}, submitted period by period over the dispatch horizon T.","Demand includes the optimal power of flexible appliances, efficiency-adjusted EV charging power, and must-run load; it must be listed separately from generation, and the total net demand alone must not be reported.","This demand declaration serves as an exogenous input to regional aggregate pricing."],"evidence_refs":["11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand::projection"]},{"unit_id":"14-stackelberg_pv_sharing::v141-a-M01::bidding.demand","retained_variants":["After receiving the internal price for the next time slot, the PV prosumer selects x_n^o and submits it to the MGO.","Hourly advance scheduling is adopted, and submission occurs after price broadcasting and flexible-load evaluation; the underlying strategy satisfies x_n^min≤x_n≤x_n^max."],"evidence_refs":["14-stackelberg_pv_sharing::v141-a-M01::bidding.demand::projection"]},{"unit_id":"39-dynamic_congestion_tariff::v141-a-M02::bidding.demand","retained_variants":["Submit to the DSO p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}), ∀t∈N_t; p is EV charging power, \\hat p is HP power, and E_i maps customers to load buses.","Given the current-round DPT, the local plan minimizes the sum of electricity cost and network charges, subject to EV operation, household thermal conditions, and HP input power limits.","The submitted quantity is provisional demand, updated in DPT iterations and used for subsequent congestion identification; it is not equivalent to the allocated electricity quantity."],"evidence_refs":["39-dynamic_congestion_tariff::v141-a-M02::bidding.demand::projection"]}],"functional":{"is_child":false,"subdivision_pending":false,"baseline_parent_id":"COMP-221ff4096aa50456","baseline_parent_code":"BID015","secondary_class":"SC-L3-e11e47541452e26e","category":{"id":"SC-L3-e11e47541452e26e","stage":"L3","label_zh":"Consumption demand quantity reporting.","definition_zh":"Participants submit to the organizer the autonomously selected consumption quantity or the electricity demand component formed by local dispatch, thereby providing information on their own consumption-side quantity decision; the consumption scope, whether it is listed separately from generation, and the specific use are retained according to source.","main_identity_axes":["Participant role reporting its own consumption arrangement.","Selected consumption quantity or electricity demand component formed by dispatch.","Function of disclosing the consumption-side quantity decision to the organizer."],"inclusion_criteria":["The object is explicitly its own consumption quantity or electricity demand component, rather than the net traded quantity after offsetting generation.","The quantity is formed by autonomous consumption choice or local dispatch and is actually reported to the organizer.","The consumption quantity may be submitted alone or, according to source requirements, submitted separately from generation."],"exclusion_criteria":["Reporting of net electricity purchase demand or net supply component.","Electricity purchase or sale intentions submitted for transaction acceptance, matching, or bilateral coordination.","Re-reported allocated quantities from other markets, regulation demand, local-only selection without a submission requirement, and exemption-from-reporting rules."],"supporting_unit_ids":["11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","14-stackelberg_pv_sharing::v141-a-M01::bidding.demand"],"status":"agent_defined_structurally_validated"},"definition":{"definition_zh":"Participants or their aggregation agents report to the organizer the quantity of consumption demand formed by autonomous choice or local dispatch; separate declaration, aggregation mapping, and provisional updates are retained according to source.","identity_fields":["Submitter: the decision-maker for consumption arrangements or its aggregation agent.","Object: the quantity of consumption demand not offset by generation.","Function: disclose the consumption-side quantity decision to the organizer."],"member_unit_ids":["11-p2p_mechanisms_evaluation::v141-a-M02::bidding.demand","14-stackelberg_pv_sharing::v141-a-M01::bidding.demand","39-dynamic_congestion_tariff::v141-a-M02::bidding.demand"]}},"canonical_pointer":"/nodes/30"});
